                     {isGenerating ? 'RENDERING...' : 'GENERATE REALITY'}
                 </LuxuryButton>
             </div>
         </div>
      </div>

      {/* RIGHT PANEL: GALLERY & PREVIEW */}
      <div className="flex-1 bg-[#050505] relative flex flex-col">
