                  />
                  <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity duration-500">
                      <LuxuryButton variant="secondary" onClick={() => handleDownload(selectedAsset, 'png')}>
