        2. OPTICAL PHYSICS: Simulate the lens character of the specified 'optics'.
        3. IDENTITY PROTECTION: If 'identity_lock' is active, strictly map the face from reference images.
        4. ANTI-CGI: Avoid all video-game artifacts. Focus on skin subsurface scattering and vellus hair.

        BLUEPRINT FOLLOWS:
        ${JSON.stringify(jsonBlueprint, null, 2)}
        `;

        const parts: any[] = [{ text: systemInstruction }];

        // Attach visual references
        const activeSubjects = state.mode === 'duo' ? state.subjects : [state.subjects[0]];
        activeSubjects.forEach((sub, i) => {
            const label = `SUBJECT_${i + 1}`;
            if (sub.baseImages?.length) {
                parts.push({ text: `\n[REFERENCE_IMAGES_FOR_${label}]` });
                sub.baseImages.forEach((img, idx) => {
                    parts.push({ inlineData: { mimeType: 'image/jpeg', data: cleanBase64(img) } });
                });
            }
            if (sub.poseReferenceImage) {
                 parts.push({ text: `\n[POSE_SKELETON_FOR_${label}]` });
